import { supabase } from './supabase';

/**
 * Fetch hazards and their consequences by event ID.
 */
export async function getHazardsByEventId(eventId) {
  try {
    const { data: hazards, error } = await supabase
      .from('hira_hazards')
      .select(`
        id,
        description,
        hira_consequences (
          id,
          description,
          current_controls
        )
      `)
      .eq('event_id', eventId)
      .order('created_at', { ascending: true });

    if (error) {
      console.error('Error fetching hazards:', error);
      throw error;
    }

    return hazards.map(hazard => ({
      hazard_id: hazard.id,
      description: hazard.description,
      consequences: hazard.hira_consequences.map(consequence => ({
        id: consequence.id,  // Keep the original id from the consequences table
        description: consequence.description,
        currentControls: consequence.current_controls,
      }))
    }));
  } catch (error) {
    console.error('Error getting hazards:', error);
    throw error;
  }
}

/**
 * Update hazards and their consequences for a specific event.
 */
export async function updateHazards(eventId, hazardsData) {
  try {
    // Fetch existing hazards for the event
    const { data: existingHazards, error: fetchError } = await supabase
      .from('hira_hazards')
      .select('id')
      .eq('event_id', eventId);

    if (fetchError) throw fetchError;

    if (existingHazards && existingHazards.length > 0) {
      // Delete existing hazards and their cascading consequences
      const { error: deleteError } = await supabase
        .from('hira_hazards')
        .delete()
        .eq('event_id', eventId);

      if (deleteError) throw deleteError;
    }

    // Insert new hazards for the event
    const hazardPromises = hazardsData.map(async hazard => {
      const { data: createdHazard, error: hazardError } = await supabase
        .from('hira_hazards')
        .insert({
          event_id: eventId,
          description: hazard.description,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        })
        .select()
        .single();

      if (hazardError) {
        console.error('Error creating hazard:', hazardError);
        throw hazardError;
      }

      // Insert consequences for the created hazard
      const consequencePromises = hazard.consequences.map(consequence => {
        console.log('Creating consequence for hazard:', {
          hazard_id: createdHazard.id,
          description: consequence.description
        });

        return supabase
          .from('hira_consequences')
          .insert({
            hazard_id: createdHazard.id,
            description: consequence.description,
            current_controls: consequence.currentControls,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString()
          })
          .select('id, description, current_controls')  // Explicitly select fields
          .single()
          .then(result => {
            if (result.error) {
              console.error('Error creating consequence:', result.error);
              throw result.error;
            }
            console.log('Created consequence:', result.data);
            return result;
          });
      });

      const consequencesResults = await Promise.all(consequencePromises);
      const consequences = consequencesResults.map(result => {
        if (result.error) throw result.error;
        return {
          id: result.data.id,
          description: result.data.description,
          currentControls: result.data.current_controls,
        };
      });

      return {
        hazard_id: createdHazard.id, // Use hazard_id consistently
        description: createdHazard.description,
        consequences,
      };
    });

    const results = await Promise.all(hazardPromises);
    return results.map(hazardResult => ({
      hazard_id: hazardResult.hazard_id,
      description: hazardResult.description,
      consequences: hazardResult.consequences.map(consequence => ({
        consequence_id: consequence.id,
        description: consequence.description,
        currentControls: consequence.currentControls,
      })),
    }));
  } catch (error) {
    console.error('Error updating hazards:', error);
    throw error;
  }
}

/**
 * Delete all hazards and their consequences for a specific event.
 */
export async function deleteHazards(eventId) {
  try {
    const { error } = await supabase
      .from('hira_hazards')
      .delete()
      .eq('event_id', eventId);

    if (error) throw error;
  } catch (error) {
    console.error('Error deleting hazards:', error);
    throw error;
  }
}
